const input = $input.first().json;
const body = input.body || input;
const intent = String(body.intent || '');
const actionId = String(body.action_id || '');
const vacancyId = Number(body.vacancy_id);
if (!intent) { throw new Error('Вход требует intent'); }
const esc = function(s) { return String(s).replace(/'/g, "''"); };
const read_action_sql = actionId ? "SELECT action_id, action_type, status, potok_candidate_id, source_vacancy_id, target_vacancy_id FROM recruiter_compass.action_proposals WHERE action_id = '" + esc(actionId) + "' LIMIT 1" : "SELECT 1 WHERE false";
const criteria_sql = "SELECT criteria FROM recruiter_compass.vacancy_criteria_versions WHERE potok_vacancy_id = " + vacancyId + " AND status = 'confirmed' ORDER BY version_number DESC LIMIT 1";
const reviews_sql = "SELECT potok_candidate_id, recommendation, summary, evidence, critical_unknowns FROM recruiter_compass.candidate_reviews WHERE potok_vacancy_id = " + vacancyId + " AND run_id = (SELECT run_id FROM recruiter_compass.candidate_reviews WHERE potok_vacancy_id = " + vacancyId + " ORDER BY created_at DESC LIMIT 1) ORDER BY potok_candidate_id";
const actions_sql = "SELECT action_type, status, potok_candidate_id, source_vacancy_id, target_vacancy_id, payload FROM recruiter_compass.action_proposals WHERE source_vacancy_id = " + vacancyId + " OR target_vacancy_id = " + vacancyId + " ORDER BY created_at";
const audit_sql = "SELECT a.event_type, a.actor_type, a.event_data FROM recruiter_compass.action_audit a JOIN recruiter_compass.action_proposals p ON a.action_id = p.action_id WHERE p.source_vacancy_id = " + vacancyId + " OR p.target_vacancy_id = " + vacancyId + " ORDER BY a.created_at";
return [{ json: { intent: intent, action_id: actionId, vacancy_id: vacancyId, read_action_sql: read_action_sql, criteria_sql: criteria_sql, reviews_sql: reviews_sql, actions_sql: actions_sql, audit_sql: audit_sql } }];

const actionId = String($('Валидировать вход').first().json.action_id);
if (!actionId) { throw new Error('confirm_action требует action_id'); }
const esc = function(s) { return String(s).replace(/'/g, "''"); };
const sql = "UPDATE recruiter_compass.action_proposals SET status = 'confirmed', recruiter_confirmed_by = 'recruiter', recruiter_confirmed_at = now() WHERE action_id = '" + esc(actionId) + "' AND status IN ('proposed','consent_required','ready_for_recruiter_confirmation') RETURNING action_id, status";
return [{ json: { action_id: actionId, sql: sql } }];

const rows = $input.all();
const confirmed = rows.some(function(r) { return r.json.status === 'confirmed'; });
return [{ json: { action_id: $('SQL подтверждения').first().json.action_id, confirmed: confirmed, status: confirmed ? 'confirmed' : 'not_found' } }];

const a = $input.first().json;
if (a.status !== 'confirmed') { throw new Error('Действие не подтверждено (status=' + a.status + ')'); }
if (a.action_type !== 'transfer_to_neighbouring_vacancy') { throw new Error('Неподдерживаемый action_type: ' + a.action_type); }
return [{ json: { action_id: a.action_id, candidate_id: Number(a.potok_candidate_id), target_vacancy_id: Number(a.target_vacancy_id), source_vacancy_id: Number(a.source_vacancy_id) } }];

const action = $('Проверить статус').first().json;
const existing = $input.first().json;
const objs = (existing && existing.objects) || [];
const already = objs.some(function(o) { return Number(o.applicant_id) === action.candidate_id; });
return [{ json: { action_id: action.action_id, candidate_id: action.candidate_id, target_vacancy_id: action.target_vacancy_id, source_vacancy_id: action.source_vacancy_id, already: already } }];

const d = $('Определить перенос').first().json;
const esc = function(s) { return String(s).replace(/'/g, "''"); };
const eventData = { idempotent: true, reason: 'candidate_already_on_target' };
const sql = "UPDATE recruiter_compass.action_proposals SET status = 'executed', executed_at = now() WHERE action_id = '" + esc(String(d.action_id)) + "' AND status = 'confirmed'; INSERT INTO recruiter_compass.action_audit (action_id, event_type, actor_type, event_data) VALUES ('" + esc(String(d.action_id)) + "', 'execution_succeeded', 'agent', '" + esc(JSON.stringify(eventData)) + "'::jsonb)";
return [{ json: { sql: sql, action_id: d.action_id, idempotent: true, target_vacancy_id: d.target_vacancy_id } }];

const d = $('Определить перенос').first().json;
const resp = $input.first().json;
const esc = function(s) { return String(s).replace(/'/g, "''"); };
const eventData = { idempotent: false, target_vacancy_id: d.target_vacancy_id, ajs_join_id: resp.id || null };
const sql = "UPDATE recruiter_compass.action_proposals SET status = 'executed', executed_at = now() WHERE action_id = '" + esc(String(d.action_id)) + "' AND status = 'confirmed'; INSERT INTO recruiter_compass.action_audit (action_id, event_type, actor_type, event_data) VALUES ('" + esc(String(d.action_id)) + "', 'execution_succeeded', 'agent', '" + esc(JSON.stringify(eventData)) + "'::jsonb)";
return [{ json: { sql: sql, action_id: d.action_id, idempotent: false, target_vacancy_id: d.target_vacancy_id } }];

const vacancy = $('Прочитать вакансию').first().json;
const criteriaRow = $('Критерии').first().json;
const reviews = $('Разборы').all();
const resumes = $('Нормализовать резюме').all();
const actions = $('Действия').all();
const audit = $('Аудит').all();
const criteria = (criteriaRow && criteriaRow.criteria) || [];
const kinds = { must_have: 0, nice_to_have: 0, constraint: 0 };
criteria.forEach(function(c) { if (c && c.kind) { kinds[c.kind] = (kinds[c.kind] || 0) + 1; } });
const titleMap = {};
criteria.forEach(function(c) { if (c && c.criterion_id) { titleMap[c.criterion_id] = c.title; } });
const nameById = {};
resumes.forEach(function(r) { nameById[r.json.applicant_id] = r.json.name; });
const breakdown = { 'continue': [], 'clarify': [], 'not_for_current_vacancy': [], 'consider_neighbour_role': [] };
reviews.forEach(function(rv) {
  const r = rv.json;
  const evidence = Array.isArray(r.evidence) ? r.evidence : [];
  const closed = evidence.filter(function(e) { return e.state === 'confirmed'; }).length;
  const gaps = Array.isArray(r.critical_unknowns) ? r.critical_unknowns : [];
  const entry = { candidate_id: String(r.potok_candidate_id), name: nameById[r.potok_candidate_id] || ('#' + r.potok_candidate_id), closed: closed, total: evidence.length, gaps: gaps.map(function(g) { return g.question || titleMap[g.criterion_id] || ''; }) };
  (breakdown[r.recommendation] || breakdown['clarify']).push(entry);
});
const actionsOut = actions.filter(function(a) { return a.json && a.json.action_type; }).map(function(a) { return { action_type: a.json.action_type, status: a.json.status, candidate_id: String(a.json.potok_candidate_id), source_vacancy_id: a.json.source_vacancy_id, target_vacancy_id: a.json.target_vacancy_id }; });
const auditOut = audit.filter(function(a) { return a.json && a.json.event_type; }).map(function(a) { return { event_type: a.json.event_type, actor_type: a.json.actor_type }; });
const criteria_list = criteria.map(function(c) { return { title: c.title, kind: c.kind }; });
return [{ json: { vacancy_name: vacancy.name || '', criteria: kinds, criteria_list: criteria_list, candidates: breakdown, actions: actionsOut, audit: auditOut } }];

